        assert row["source_flags"]["has_intel"] is False
        assert row["source_flags"]["has_app_ports"] is True
        assert row["open_ports"] == []
        assert row["port_provenance"]["divergence"] == {
            "app_only": [443],
            "provider_only": [],
            "has_drift": False,
        }

