            ("virustotal", ("domain", "hash"), ("VT_API_KEY", "VTCLI_APIKEY"), "Free signup; paid tiers"),
            ("teamcymru", ("ip",), (), "Free public lookup"),
            ("nvd", ("cve",), (), "Free public lookup"),
            ("urlhaus", ("ip", "domain", "hash", "url"), ("URLHAUS_AUTH_KEY",), "Free abuse.ch Auth-Key"),
