    def test_intel_cache_and_rate_decode_failures_log_safe_warnings(self):
        from services.intel import cache, rate_limiter

        redis = process._FakeRedisClient()
        redis.set(cache.cache_key("fofa", "domain", "secret.example"), "{not-json")
        redis.set(cache.quota_cache_key("tok_cache_decode", "fofa"), "{not-json")
        redis.set("intel:rate:tok_cache_decode:fofa", "{not-json")

        with mock.patch.object(cache.log, "warning") as cache_warning:
            assert cache.get_cached_response("fofa", "domain", "secret.example", redis_client=redis) is None
            assert cache.get_quota_exhausted("tok_cache_decode", "fofa", redis_client=redis) is None

        cache_events = {call.args[0]: call.kwargs["extra"] for call in cache_warning.call_args_list}
        assert cache_events["INTEL_CACHE_DECODE_FAILED"]["provider"] == "fofa"
        assert cache_events["INTEL_CACHE_DECODE_FAILED"]["entity_type"] == "domain"
        assert "secret.example" not in json.dumps(cache_events)
        assert cache_events["INTEL_QUOTA_CACHE_DECODE_FAILED"]["session"] == "tok_cach********"

        with mock.patch.object(rate_limiter.log, "warning") as rate_warning:
            assert rate_limiter.check_rate_limit(
                "tok_cache_decode",
                "fofa",
                cfg={"intel_rate_limit_fofa_bucket": 1, "intel_rate_limit_fofa_refill_seconds": 10},
                redis_client=redis,
                now=100.0,
            ).allowed is True

        rate_warning.assert_called_once()
        assert rate_warning.call_args.args == ("INTEL_RATE_BUCKET_DECODE_FAILED",)
        assert rate_warning.call_args.kwargs["extra"]["provider"] == "fofa"
        assert rate_warning.call_args.kwargs["extra"]["session"] == "tok_cach********"

    def test_json_api_client_uses_system_ca_bundle_for_https(self, monkeypatch):
        from services.intel import clients

        contexts = []
        connections = []

        class FakeResponse:
            status = 200

            def read(self):
                return b'{"ok": true}'

            def getheader(self, name):  # noqa: ARG002
                return None

        class FakeHttpsConnection:
            def __init__(self, host, *, timeout, context):
                self.host = host
                self.timeout = timeout
                self.context = context
                connections.append(self)

            def request(self, method, path, headers=None):
                self.method = method
                self.path = path
                self.headers = headers or {}

            def getresponse(self):
                return FakeResponse()

            def close(self):
                self.closed = True

        monkeypatch.delenv("SSL_CERT_FILE", raising=False)
        monkeypatch.delenv("REQUESTS_CA_BUNDLE", raising=False)
        monkeypatch.delenv("SSL_CERT_DIR", raising=False)
        monkeypatch.setattr(clients.os.path, "exists", lambda path: path == "/etc/ssl/certs/ca-certificates.crt")
        monkeypatch.setattr(clients.ssl, "create_default_context", lambda **kwargs: contexts.append(kwargs) or "ctx")
        monkeypatch.setattr(clients.http.client, "HTTPSConnection", FakeHttpsConnection)

        loaded = clients.JsonApiClient()._json_request("https://provider.example.test/v1?x=1")

        assert loaded == {"ok": True}
        assert contexts == [{"cafile": "/etc/ssl/certs/ca-certificates.crt"}]
        assert connections[0].host == "provider.example.test"
        assert connections[0].context == "ctx"
        assert connections[0].path == "/v1?x=1"

    def test_json_api_client_rejects_cross_origin_redirects_before_forwarding_secrets(self, monkeypatch):
        from services.intel import clients
        from services.intel.base import ProviderApiError

        connections = []

        class FakeResponse:
            def __init__(self, status, body=b"{}", location=None):
                self.status = status
                self._body = body
                self._location = location

            def read(self):
                return self._body

            def getheader(self, name):
                return self._location if name.lower() == "location" else None

        class FakeHttpsConnection:
            def __init__(self, host, *, timeout, context):
                self.host = host
                self.timeout = timeout
                self.context = context
                connections.append(self)

            def request(self, method, path, body=None, headers=None):
                self.method = method
                self.path = path
                self.body = body
                self.headers = headers or {}

            def getresponse(self):
                assert self.host == "provider.example.test"
                return FakeResponse(302, location="https://evil.example.test/collect")

            def close(self):
                self.closed = True

        monkeypatch.setattr(clients.ssl, "create_default_context", lambda **kwargs: "ctx")
        monkeypatch.setattr(clients.http.client, "HTTPSConnection", FakeHttpsConnection)

        with pytest.raises(ProviderApiError, match="untrusted host"):
            clients.JsonApiClient()._json_request(
                "https://provider.example.test/v1",
                headers={"x-apikey": "secret-token"},
            )

        assert len(connections) == 1
        assert connections[0].headers == {"x-apikey": "secret-token"}

