            pty_service._meta_key(run_id),
            json.dumps({
                "run_id": run_id,
                "session_id": "session-1",
                "command": "telnet --interactive telnet towel.blinkenlights.nl",
                "started": "2026-01-01T00:00:00Z",
                "rows": 24,
                "cols": 100,
                "closed": False,
            }),
