        assert "Server lookup failure" in chunks[0]
        assert '"type": "output"' in chunks[0]
        assert '"code": 1' in chunks[1]
        assert '"type": "exit"' in chunks[1]
        assert "PTY run is no longer active" not in "".join(chunks)

