    def test_atlas_import_parser_enforces_row_and_element_limits(self):
        csv_payload = "\n".join((
            "row_type,entity_kind,entity_value",
            "entity,domain,one.darklab.sh",
            "entity,domain,two.darklab.sh",
        ))
        xml_payload = "<issues><issue><name>One</name></issue></issues>"

        with pytest.raises(ImportParseError, match="row limit"):
            parse_import_file(csv_payload, format_id="generic_csv", limits=ImportParserLimits(max_rows=1))
        with pytest.raises(ImportParseError, match="XML element limit"):
            parse_import_file(xml_payload, format_id="burp_xml", limits=ImportParserLimits(max_xml_elements=1))

    def test_atlas_import_parser_enforces_upload_and_warning_limits(self):
        warning_payload = "\n".join((
            '{"row_type":"entity","entity_kind":"banana","entity_value":"one.example"}',
            '{"row_type":"entity","entity_kind":"banana","entity_value":"two.example"}',
        ))

        with mock.patch("services.atlas.import_parser.log.debug") as mock_debug, \
                mock.patch("services.atlas.import_parser.log.warning") as mock_warning:
            result = parse_import_file(
                warning_payload,
                format_id="generic_jsonl",
                limits=ImportParserLimits(max_warnings=1),
            )

        assert result.skipped_count == 2
        assert len(result.warnings) == 1
        assert result.warnings[0].code == "invalid_entity_kind"
        assert result.suppressed_warning_count == 1
        debug_events = [call.args[0] for call in mock_debug.call_args_list]
        assert debug_events == ["ATLAS_IMPORT_PARSE_STARTED", "ATLAS_IMPORT_PARSE_COMPLETED"]
        started_extra = mock_debug.call_args_list[0].kwargs["extra"]
        completed_extra = mock_debug.call_args_list[1].kwargs["extra"]
        assert started_extra["format_id"] == "generic_jsonl"
        assert started_extra["upload_bytes"] == len(warning_payload.encode("utf-8"))
        assert started_extra["expanded_bytes"] == len(warning_payload.encode("utf-8"))
        assert started_extra["compression"] == "none"
        assert started_extra["max_warnings"] == 1
        assert completed_extra["rows"] == 2
        assert completed_extra["warning_count"] == 1
        assert completed_extra["suppressed_warning_count"] == 1
        assert completed_extra["warning_codes"] == {"invalid_entity_kind": 1}
        truncated_extra = next(
            call.kwargs["extra"]
            for call in mock_warning.call_args_list
            if call.args[0] == "ATLAS_IMPORT_WARNINGS_TRUNCATED"
        )
        assert truncated_extra["format_id"] == "generic_jsonl"
        assert truncated_extra["skipped"] == 2
        assert truncated_extra["warning_count"] == 1
        assert truncated_extra["suppressed_warning_count"] == 1
        assert truncated_extra["max_warnings"] == 1
        assert truncated_extra["warning_codes"] == {"invalid_entity_kind": 1}
        assert result.to_dict()["suppressed_warning_count"] == 1

        class RecordingSource:
            def __init__(self):
                self.read_sizes = []

            def read(self, size=-1):
                self.read_sizes.append(size)
                return b"x" * size

        source = RecordingSource()
        with pytest.raises(ImportParseError, match="byte limit"):
            parse_import_file(b"x" * 5, format_id="generic_csv", limits=ImportParserLimits(max_upload_bytes=4))
        with pytest.raises(ImportParseError, match="byte limit"):
            parse_import_file(cast(IO[bytes], source), format_id="generic_csv", limits=ImportParserLimits(max_upload_bytes=4))
        assert source.read_sizes == [5]

    def test_atlas_import_parser_accepts_bounded_gzip_and_single_report_zip(self):
        payload = (
            b"row_type,entity_kind,entity_value\n"
            b"entity,domain,compressed.darklab.sh\n"
        )
        gzip_payload = gzip.compress(payload)
        zip_buffer = io.BytesIO()
        with zipfile.ZipFile(zip_buffer, mode="w", compression=zipfile.ZIP_DEFLATED) as archive:
            archive.writestr("reports/atlas.csv", payload)

        with mock.patch("services.atlas.import_parser.log.debug") as mock_debug:
            gzip_result = parse_import_file(gzip_payload, format_id="generic_csv")
        zip_result = parse_import_file(zip_buffer.getvalue(), format_id="generic_csv")

        assert [entity.canonical_value for entity in gzip_result.entities] == ["compressed.darklab.sh"]
        assert [entity.canonical_value for entity in zip_result.entities] == ["compressed.darklab.sh"]
        started_extra = mock_debug.call_args_list[0].kwargs["extra"]
        assert started_extra["upload_bytes"] == len(gzip_payload)
        assert started_extra["expanded_bytes"] == len(payload)
        assert started_extra["compression"] == "gzip"

    def test_atlas_import_parser_rejects_unsafe_or_ambiguous_archives(self):
        payload = b"row_type,entity_kind,entity_value\nentity,domain,archive.darklab.sh\n"

        def zipped(*members):
            buffer = io.BytesIO()
            with zipfile.ZipFile(buffer, mode="w", compression=zipfile.ZIP_DEFLATED) as archive:
                for name, content in members:
                    archive.writestr(name, content)
            return buffer.getvalue()

        with pytest.raises(ImportParseError, match="exactly one"):
            parse_import_file(
                zipped(("first.csv", payload), ("second.csv", payload)),
                format_id="generic_csv",
            )
        many_entries = [(f"directory-{index}/", b"") for index in range(16)]
        with pytest.raises(ImportParseError, match="entry limit"):
            parse_import_file(zipped(*many_entries, ("report.csv", payload)), format_id="generic_csv")
        with pytest.raises(ImportParseError, match="unsafe report path"):
            parse_import_file(zipped(("../report.csv", payload)), format_id="generic_csv")
        symlink_buffer = io.BytesIO()
        symlink_info = zipfile.ZipInfo("report.csv")
        symlink_info.create_system = 3
        symlink_info.external_attr = (stat.S_IFLNK | 0o777) << 16
        with zipfile.ZipFile(symlink_buffer, mode="w") as archive:
            archive.writestr(symlink_info, "target.csv")
        with pytest.raises(ImportParseError, match="regular file"):
            parse_import_file(symlink_buffer.getvalue(), format_id="generic_csv")
        encrypted = bytearray(zipped(("report.csv", payload)))
        for signature, flag_offset in ((b"PK\x03\x04", 6), (b"PK\x01\x02", 8)):
            header_offset = encrypted.find(signature)
            flags = int.from_bytes(encrypted[header_offset + flag_offset:header_offset + flag_offset + 2], "little")
            encrypted[header_offset + flag_offset:header_offset + flag_offset + 2] = (flags | 1).to_bytes(2, "little")
        with pytest.raises(ImportParseError, match="Encrypted ZIP"):
            parse_import_file(bytes(encrypted), format_id="generic_csv")
        with pytest.raises(ImportParseError, match="Nested compressed"):
            parse_import_file(gzip.compress(gzip.compress(payload)), format_id="generic_csv")
        with pytest.raises(ImportParseError, match="malformed or incomplete"):
            parse_import_file(b"\x1f\x8btruncated", format_id="generic_csv")

    def test_atlas_import_parser_rejects_expansion_over_configured_limit(self):
        payload = (
            b"row_type,entity_kind,entity_value\n"
            b"entity,domain,expanded.darklab.sh\n"
        )
        limit = len(payload) - 1

        with pytest.raises(ImportParseError, match="Expanded import"):
            parse_import_file(
                gzip.compress(payload),
                format_id="generic_csv",
                limits=ImportParserLimits(max_expanded_bytes=limit),
            )

        zip_buffer = io.BytesIO()
        with zipfile.ZipFile(zip_buffer, mode="w", compression=zipfile.ZIP_DEFLATED) as archive:
            archive.writestr("report.csv", payload)
        with pytest.raises(ImportParseError, match="Expanded import"):
            parse_import_file(
                zip_buffer.getvalue(),
                format_id="generic_csv",
                limits=ImportParserLimits(max_expanded_bytes=limit),
            )

    def test_materializes_run_entities_from_output_entries(self):
        from core.helpers import get_log_session_id

        with tempfile.TemporaryDirectory() as tmp:
            db_path = self._fresh_db(tmp)
            self._create_tables(db_path)
            conn = sqlite3.connect(db_path)
            conn.row_factory = sqlite3.Row
            conn.execute(
                "INSERT INTO runs (id, session_id, command, started, output_preview) VALUES (?, ?, ?, ?, ?)",
                ("run-atlas", "atlas-session", "nmap darklab.sh", "2026-05-14T00:00:00+00:00", "[]"),
            )
            gau_metadata = OutputSignalClassifier(
                "gau example.com",
                source_run_id="run-atlas",
            ).classify_line("https://example.com/path")
            gau_entities = gau_metadata["entities"]
            assert isinstance(gau_entities, list)
            recorded = materialize_run_entities(
                conn,
                "atlas-session",
                "run-atlas",
                [
                    {
                        "text": "darklab.sh has address 203.0.113.10",
                        "entities": [
                            {"type": "domain", "value": "darklab.sh", "canonical_value": "darklab.sh"},
                            {"type": "domain", "value": "DarkLab.SH", "canonical_value": "darklab.sh"},
                            {"type": "host", "value": "WWW.DarkLab.SH.", "canonical_value": "www.darklab.sh"},
                            {"type": "ip", "value": "2001:0db8::0001", "canonical_value": "2001:db8::1"},
                            {"type": "hash", "value": "A" * 40, "canonical_value": f"sha1:{'a' * 40}"},
                            {"type": "cve", "value": "cve-2025-49113", "canonical_value": "CVE-2025-49113"},
                            *gau_entities,
                            {"type": "domain", "value": "<redacted>", "canonical_value": REDACTED_ENTITY_SENTINEL},
                        ],
                    }
                ],
                seen_at="2026-05-14T00:00:01+00:00",
            )
            conn.commit()
            entity_rows = conn.execute(
                "SELECT id, type, canonical_value, occurrence_count, host_entity_id, attributes_json "
                "FROM entities ORDER BY type, canonical_value"
            ).fetchall()
            link_rows = conn.execute(
                "SELECT run_id, occurrence_count FROM entity_run_links ORDER BY run_id"
            ).fetchall()
            domain_id = next(row["id"] for row in entity_rows if row["canonical_value"] == "darklab.sh")
            conn.execute("UPDATE entities SET attributes_json = ? WHERE id = ?", ("{not-json", domain_id))
            with mock.patch("services.atlas.materializer.log.warning") as warning_log:
                materialize_run_entities(
                    conn,
                    "atlas-session",
                    "run-atlas",
                    [{"entities": [{"type": "domain", "value": "darklab.sh", "attributes": {"source": "manual"}}]}],
                    seen_at="2026-05-14T00:00:02+00:00",
                )
            conn.close()

        assert {(row["type"], row["canonical_value"], row["occurrence_count"]) for row in entity_rows} == {
            ("cve", "CVE-2025-49113", 1),
            ("domain", "darklab.sh", 2),
            ("domain", "example.com", 1),
            ("domain", "www.darklab.sh", 1),
            ("hash", f"sha1:{'a' * 40}", 1),
            ("ip", "2001:db8::1", 1),
            ("url", "https://example.com/path", 1),
        }
        example_host_id = next(row["id"] for row in entity_rows if row["canonical_value"] == "example.com")
        url_row = next(row for row in entity_rows if row["canonical_value"] == "https://example.com/path")
        assert url_row["host_entity_id"] == example_host_id
        assert json.loads(url_row["attributes_json"]) == {
            "discovery_mode": "passive",
            "provider": "gau",
            "source_run_id": "run-atlas",
        }
        assert len(recorded) == 7
        assert [row["run_id"] for row in link_rows] == ["run-atlas"] * 7
        warning_events = {call.args[0]: call.kwargs["extra"] for call in warning_log.call_args_list}
        assert warning_events["ATLAS_ENTITY_ATTRIBUTES_DECODE_FAILED"] == {
            "session": get_log_session_id("atlas-session"),
            "entity_id": domain_id,
            "entity_type": "domain",
            "value_type": "str",
            "reason": "invalid_json",
        }

    def test_url_entities_create_and_link_host_entities(self):
        from services.atlas.materializer import upsert_entity

        with tempfile.TemporaryDirectory() as tmp:
            db_path = self._fresh_db(tmp)
            self._create_tables(db_path)
            conn = sqlite3.connect(db_path)
            conn.row_factory = sqlite3.Row
            conn.execute(
                "INSERT INTO runs (id, session_id, command, started, output_preview) VALUES (?, ?, ?, ?, ?)",
                ("run-url-atlas", "atlas-session", "curl https://api.example.com/login", "2026-05-14T00:00:00+00:00", "[]"),
            )
            recorded = materialize_run_entities(
                conn,
                "atlas-session",
                "run-url-atlas",
                [{"entities": [{"type": "url", "value": "https://api.example.com/login"}]}],
                seen_at="2026-05-14T00:00:01+00:00",
                command="curl https://api.example.com/login",
            )
            ip_url_id = upsert_entity(
                conn,
                "atlas-session",
                "url",
                "https://192.0.2.10/status",
                seen_at="2026-05-14T00:00:02+00:00",
                occurrence_count=0,
            )
            ipv6_url_id = upsert_entity(
                conn,
                "atlas-session",
                "url",
                "http://[2001:db8::1]:8080/status",
                seen_at="2026-05-14T00:00:03+00:00",
                occurrence_count=0,
            )
            conn.commit()
            rows = {
                (row["type"], row["canonical_value"]): dict(row)
                for row in conn.execute(
                    "SELECT id, type, canonical_value, host_entity_id, occurrence_count "
                    "FROM entities ORDER BY type, canonical_value"
                ).fetchall()
            }
            link_rows = conn.execute(
                "SELECT entity_id, occurrence_count FROM entity_run_links WHERE run_id = ? ORDER BY entity_id",
                ("run-url-atlas",),
            ).fetchall()
            conn.close()

        host_row = rows[("domain", "api.example.com")]
        url_row = rows[("url", "https://api.example.com/login")]
        ip_host_row = rows[("ip", "192.0.2.10")]
        ip_url_row = rows[("url", "https://192.0.2.10/status")]
        ipv6_host_row = rows[("ip", "2001:db8::1")]
        ipv6_url_row = rows[("url", "http://[2001:db8::1]:8080/status")]
        assert [item["type"] for item in recorded] == ["domain", "url"]
        assert url_row["host_entity_id"] == host_row["id"]
        assert host_row["occurrence_count"] == 1
        assert ip_url_id == ip_url_row["id"]
        assert ip_url_row["host_entity_id"] == ip_host_row["id"]
        assert ipv6_url_id == ipv6_url_row["id"]
        assert ipv6_url_row["host_entity_id"] == ipv6_host_row["id"]
        assert ("domain", "2001") not in rows
        assert {(row["entity_id"], row["occurrence_count"]) for row in link_rows} == {
            (host_row["id"], 1),
            (url_row["id"], 1),
        }

    def test_materialized_url_host_from_extracted_entities_is_not_double_counted(self):
        with tempfile.TemporaryDirectory() as tmp:
            db_path = self._fresh_db(tmp)
            self._create_tables(db_path)
            conn = sqlite3.connect(db_path)
            conn.row_factory = sqlite3.Row
            conn.execute(
                "INSERT INTO runs (id, session_id, command, started, output_preview) VALUES (?, ?, ?, ?, ?)",
                ("run-url-extracted", "atlas-session", "curl https://api.example.com/login", "2026-05-14T00:00:00+00:00", "[]"),
            )
            recorded = materialize_run_entities(
                conn,
                "atlas-session",
                "run-url-extracted",
                [{"entities": extract_entities("visit https://api.example.com/login now")}],
                seen_at="2026-05-14T00:00:01+00:00",
                command="curl https://api.example.com/login",
            )
            conn.execute(
                "INSERT INTO runs (id, session_id, command, started, output_preview) VALUES (?, ?, ?, ?, ?)",
                (
                    "run-private-url-extracted",
                    "atlas-session",
                    "curl http://127.0.0.1/private",
                    "2026-05-14T00:00:02+00:00",
                    "[]"
                ),
            )
            private_recorded = materialize_run_entities(
                conn,
                "atlas-session",
                "run-private-url-extracted",
                [{"entities": extract_entities("visit http://127.0.0.1/private now")}],
                seen_at="2026-05-14T00:00:03+00:00",
                command="curl http://127.0.0.1/private",
            )
            conn.execute(
                "INSERT INTO runs (id, session_id, command, started, output_preview) VALUES (?, ?, ?, ?, ?)",
                (
                    "run-url-extracted-repeat",
                    "atlas-session",
                    "curl https://api.example.com/login",
                    "2026-05-14T00:00:04+00:00",
                    "[]",
                ),
            )
            repeat_recorded = materialize_run_entities(
                conn,
                "atlas-session",
                "run-url-extracted-repeat",
                [
                    {"entities": extract_entities("visit https://api.example.com/login now")},
                    {"entities": extract_entities("visit https://api.example.com/login again")},
                ],
                seen_at="2026-05-14T00:00:05+00:00",
                command="curl https://api.example.com/login",
            )
            conn.commit()
            rows = {
                (row["type"], row["canonical_value"]): dict(row)
                for row in conn.execute(
                    "SELECT id, type, canonical_value, host_entity_id, occurrence_count "
                    "FROM entities ORDER BY type, canonical_value"
                ).fetchall()
            }
            link_rows = conn.execute(
                "SELECT entity_id, occurrence_count FROM entity_run_links WHERE run_id = ? ORDER BY entity_id",
                ("run-url-extracted",),
            ).fetchall()
            repeat_link_rows = conn.execute(
                "SELECT entity_id, occurrence_count FROM entity_run_links WHERE run_id = ? ORDER BY entity_id",
                ("run-url-extracted-repeat",),
            ).fetchall()
            conn.close()

        host_row = rows[("domain", "api.example.com")]
        url_row = rows[("url", "https://api.example.com/login")]
        assert [item["type"] for item in recorded] == ["domain", "url"]
        assert host_row["occurrence_count"] == 3
        assert url_row["occurrence_count"] == 3
        assert url_row["host_entity_id"] == host_row["id"]
        assert private_recorded == []
        assert [
            (item["type"], item["canonical_value"], item["occurrence_count"])
            for item in repeat_recorded
        ] == [
            ("domain", "api.example.com", 2),
            ("url", "https://api.example.com/login", 2),
        ]
        assert ("url", "http://127.0.0.1/private") not in rows
        assert ("ip", "127.0.0.1") not in rows
        assert {(row["entity_id"], row["occurrence_count"]) for row in link_rows} == {
            (host_row["id"], 1),
            (url_row["id"], 1),
        }
        assert {(row["entity_id"], row["occurrence_count"]) for row in repeat_link_rows} == {
            (host_row["id"], 2),
            (url_row["id"], 2),
        }

